package com.smarthub.plus;
import android.content.*;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.time.*;import java.time.format.DateTimeFormatter;
/** User-selected coordinates, optional Basra default; no location permission or inferred GPS. */
final class WeatherRepository {
 private static final ExecutorService work=Executors.newSingleThreadExecutor();private static boolean busy;private static long attempted;
 static synchronized void update(Context c){SharedPreferences p=c.getSharedPreferences("smarthub",0);if(!p.getBoolean("osd_weather",false)||busy||System.currentTimeMillis()-attempted<30*60000L)return;busy=true;attempted=System.currentTimeMillis();work.execute(()->{try{double lat=Double.parseDouble(p.getString("weather_lat","30.5081")),lon=Double.parseDouble(p.getString("weather_lon","47.7835"));if(!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new IllegalArgumentException();String url="https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,weather_code&timezone=Asia%2FBaghdad";DirectHttp.Reply reply=DirectHttp.request(url,Collections.emptyMap(),null,256*1024,null);if(reply.code!=200)throw new Exception("HTTP "+reply.code);JSONObject data=new JSONObject(new String(reply.bytes,java.nio.charset.StandardCharsets.UTF_8)).getJSONObject("current");if(data.isNull("temperature_2m")||data.isNull("weather_code"))throw new Exception("No current weather");p.edit().putString("weather_temp",data.get("temperature_2m").toString()).putInt("weather_code",data.getInt("weather_code")).putLong("weather_at",System.currentTimeMillis()).putString("weather_for",lat+","+lon).putString("weather_error","").apply();}catch(Exception e){p.edit().putString("weather_error","Weather unavailable; check network / coordinates").apply();}finally{synchronized(WeatherRepository.class){busy=false;}}});}
 static String label(Context c){SharedPreferences p=c.getSharedPreferences("smarthub",0);if(!p.getBoolean("osd_weather",false))return "";long at=p.getLong("weather_at",0);String position=p.getString("weather_lat","30.5081")+","+p.getString("weather_lon","47.7835");if(at==0||!position.equals(p.getString("weather_for","")))return "Weather unavailable";int code=p.getInt("weather_code",-1);String icon=code==0?"☀":code<=3?"☁":code==45||code==48?"≋":code>=71&&code<=77?"❄":code>=95?"ϟ":"☂";String condition=code==0?"Clear":code<=3?"Cloudy":code==45||code==48?"Fog":code>=71&&code<=77?"Snow":code>=95?"Thunderstorm":"Rain";return p.getString("weather_city","Basra, Iraq")+" · "+icon+condition+" "+p.getString("weather_temp","")+"°C\nOpen-Meteo · "+DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.of("Asia/Baghdad")).format(Instant.ofEpochMilli(at))+(System.currentTimeMillis()-at>60*60000L||!p.getString("weather_error","").isEmpty()?" · saved / offline":"");}
}
